contract InvMutTest {
    C c;
    constructor() { c = new C(); }
    function __ESBMC_reverted() internal returns (bool) {}
    function __ESBMC_assume(bool) internal pure {}

    function run(uint256 reqID, bool repayDirect, bool isCallback) public payable {
        require(true);

        // The request must not be active before the attempt.
        bool activeBefore = c.isActive(reqID); if (__ESBMC_reverted()) return;
        require(!activeBefore);

        // clearRequest on an inactive/nonexistent request must revert.
        bool reverted;
        c.clearRequest(reqID, repayDirect, isCallback); bool __rev0 = __ESBMC_reverted(); if (__rev0) {
            reverted = true;
        } else {
            reverted = false;
        }

        // And it must remain inactive afterwards.
        bool activeAfter = c.isActive(reqID); if (__ESBMC_reverted()) return;

        assert(reverted && !activeAfter);
    }

    receive() external payable {}
}

