pragma solidity ^0.8.0;

import {Test} from "forge-std/Test.sol";
import {Cooler} from "../src/Cooler.sol";

contract InvMutTest is Test {
    uint256 internal constant VALUE_CAP = 1000000000000000000000000000000;
    Cooler c;

    function setUp() public {
        c = new Cooler();
    }

    function _run(uint256 reqID, bool repayDirect, bool isCallback) internal {
        vm.assume(true);
        bool activeBefore;
        try c.isActive(reqID) returns (bool __r) { activeBefore = __r; } catch { return; }
        vm.assume(!activeBefore);
        bool reverted;
        try c.clearRequest(reqID, repayDirect, isCallback) {
            reverted = false;
        } catch {
            reverted = true;
        }
        bool activeAfter;
        try c.isActive(reqID) returns (bool __r) { activeAfter = __r; } catch { return; }
        assertTrue(reverted && !activeAfter);
    }

    function testFuzz_run(uint256 reqID, bool repayDirect, bool isCallback) public {
        _run(reqID, repayDirect, isCallback);
    }

    receive() external payable {}
}
